while active:
    active.sort(); t,u=active.pop(0)
    if best.get(u,INF)<t: continue
    for tt,v in adj.get(u,[]):
        if tt<t: continue
        if u!=1885 and tt-t>D: break
        if tt<best.get(v,INF):
            best[v]=tt; parent[v]=(u,t,tt); active.append((tt,v))
print("undirected reached:",len(best), 1460 in best, best.get(1460))
